#!/usr/bin/env bash
# Compiles the pool coin tables' referee (the app's own physics, rules and
# Chip) to JavaScript for the pool-table Edge Function. Run after changing
# anything under lib/features/pool/domain, then deploy pool-table.
set -euo pipefail
cd "$(dirname "$0")/.."
OUT=supabase/functions/pool-table/referee.js
dart compile js -O4 lib/web_workers/pool_referee_js.dart -o "$OUT"
rm -f "$OUT.deps" "$OUT.map"
# Compiled JavaScript isn't written to lint style: CI lints the functions,
# so it's marked as generated and skipped.
{
  printf '%s\n' \
    '// Generated by tool/build_pool_referee.sh from lib/web_workers/pool_referee_js.dart.' \
    '// Do not edit: rebuild it instead.' \
    '// deno-lint-ignore-file'
  cat "$OUT"
} > "$OUT.tmp" && mv "$OUT.tmp" "$OUT"
echo "Built $OUT ($(wc -c < "$OUT") bytes)"
